-- Migration 165: наполнение погоды спец-отчёта «Данные по годам»
-- БД: YC system. Накат с ноутбука:
--   node migrations/run_local.mjs migrations/165_seed_weekly_weather.sql
--
-- Владелец 28.08: «Наполни данными про погоду отчёт из таблицы, что я тебе
-- скинул + реальные метеоданные».
--
-- Источники:
--   * manual_text — ЖИВЫЕ комментарии из «Данные по годам.xlsx», лист «2026»,
--     колонки «Погода СПБ» (C), «Погода МСК» (BP), «Погода КРД» (DE). Неделя
--     определена по подписи строки файла («12-18 января» → 2026-01-12).
--     Перенесено комментариев: 83 (СПб 30, КРД 27, МСК 26).
--     manual_author_bitrix_id = 'xlsx-import' — метка происхождения: видно, что
--     это импорт из файла, а не ответ ответственного боту.
--   * auto_summary/auto_data — архив Open-Meteo (бесплатно, без ключа) по
--     координатам трёх городов, агрегировано по ISO-неделям (мин/макс
--     температура, суммы осадков и снега): 105 недель, включая те, где живого
--     комментария в файле не было.
--
-- Идемпотентно: повторный накат обновляет автосводку и НЕ затирает живой текст
-- (COALESCE на manual_text).

ON CONFLICT (city, week_start) DO UPDATE SET
  manual_text = COALESCE(EXCLUDED.manual_text, weekly_weather.manual_text),
  manual_author_bitrix_id = COALESCE(EXCLUDED.manual_author_bitrix_id, weekly_weather.manual_author_bitrix_id),
  answered_at = COALESCE(EXCLUDED.answered_at, weekly_weather.answered_at),
  auto_summary = COALESCE(EXCLUDED.auto_summary, weekly_weather.auto_summary),
  auto_data = COALESCE(EXCLUDED.auto_data, weekly_weather.auto_data),
  updated_at = now();

-- Проверка:
--   SELECT city, count(*) FILTER (WHERE manual_text IS NOT NULL) AS живых,
--          count(*) FILTER (WHERE auto_summary IS NOT NULL) AS авто
--     FROM weekly_weather GROUP BY city ORDER BY city;
